import threading

counter = 0
lock = threading.Lock()

def increment():
    global counter
    for _ in range(100000):
        with lock:  # Acquire and auto-release
            counter += 1

# Without lock (race condition):
counter_no_lock = 0
def increment_bad():
    global counter_no_lock
    for _ in range(100000):
        counter_no_lock += 1  # Race condition!

threads = [threading.Thread(target=increment) for _ in range(5)]
for t in threads: t.start()
for t in threads: t.join()
print(f"With lock: {counter}")  # Always 500000

threads = [threading.Thread(target=increment_bad) for _ in range(5)]
for t in threads: t.start()
for t in threads: t.join()
print(f"Without lock: {counter_no_lock}")  # May be < 500000!

# Lock with timeout:
if lock.acquire(timeout=5):
    try:
        # Critical section
        pass
    finally:
        lock.release()

# RLock — reentrant lock (same thread can re-acquire):
rlock = threading.RLock()
def recursive_func(n):
    with rlock:
        if n > 0:
            recursive_func(n - 1)  # Same thread re-enters

